"""Build the bounded N2 block-hidden math operators with the pinned Hike toolchain."""
import hashlib,json,os,re,subprocess
from pathlib import Path
r=Path(__file__).resolve().parent;t=Path(os.environ['DIFFUSION_TOOLCHAIN']).resolve();sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();p=json.loads((t/'provenance.json').read_text())
assert p['hikeCommit']=='3c51fde6675f317453919bd505d0e2d0f638e7f1';assert sha(t/'hikec')=='fb4588cba306b8dded91ad02735254681eaca08fa997f55919185cd607e89b26'
command=[str(t/'hikec'),'build','-target','wabt','-wasm-mode','normal','-o',str(r/'kernel.wasm'),str(r/'math.hike')]
env=dict(os.environ,PATH=str(t/'wabt/node_modules/.bin')+os.pathsep+os.environ['PATH']);run=subprocess.run(command,env=env,capture_output=True,text=True);(r/'build.log').write_text(run.stdout+run.stderr);run.check_returncode()
runtime=r/'runtime.js';runtime.write_text('\n'.join(line.rstrip() for line in runtime.read_text().splitlines()).rstrip()+'\n')
subprocess.run(['node',str(t/'wabt/node_modules/wabt/bin/wasm2wat'),str(r/'kernel.wasm'),'-o',str(r/'kernel.wat')],check=True);wat=(r/'kernel.wat').read_text()
imports={'cos':'f64','sin':'f64','pow':'f64 f64','sqrt':'f64'}
assert set(re.findall(r'\(import "env" "([^"]+)"',wat))==set(imports)
for name,signature in imports.items():
 m=re.search(r'\(import "env" "'+name+r'" \(func \(;\d+;\) \(type (\d+)\)\)\)',wat);assert m,name
 assert re.search(r'\(type \(;'+m[1]+r';\) \(func \(param '+signature+r'\) \(result f64\)\)\)',wat),name
abi={'Sinusoidal':'f32 i32 i32','LayerNorm':'i32 i32 i32 i32','Add':'i32 i32 i32 i32 i32','Modulate':'i32 i32 i32 i32 i32 i32'}
for name,signature in abi.items():
 idx=re.search(r'\(export "'+name+r'" \(func (\d+)\)\)',wat)[1];assert re.search(r'\(func \(;'+idx+r';\) \(type \d+\) \(param '+signature+r'\) \(result i32\)',wat),name
h=sha(r/'kernel.wasm');(r/'registry.mjs').write_text('// Generated by block-hidden/build.py\nexport const BLOCK_HIDDEN_MATH_SHA256='+json.dumps(h)+';\n')
record={'hikeCommit':p['hikeCommit'],'compilerSha256':sha(t/'hikec'),'backend':'wabt','mode':'normal','sourceSha256':sha(r/'math.hike'),'hostSha256':sha(r/'math.mjs'),'builderSha256':sha(Path(__file__)),'wasmSha256':h,'watSha256':sha(r/'kernel.wat'),'runtimeSha256':sha(runtime),'imports':[{'module':'env','name':name,'signature':signature+' -> f64','bridge':'fixed ECMAScript Math.'+name} for name,signature in imports.items()],'abi':abi,'command':command,'versions':p['versions'],'scope':'natural N2 full5120 nonaffine LayerNorm, sinusoidal256 and modulation F32 diagnostic; not full block/model or production precision parity'};(r/'build-record.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'wasmSha256':h,'bytes':(r/'kernel.wasm').stat().st_size}))
